CREATE POLICY "Public can view bookings" ON public.bookings FOR SELECT TO anon, authenticated USING (true); CREATE POLICY "Public can delete bookings" ON public.bookings FOR DELETE TO anon, authenticated USING (true); CREATE POLICY "Public can update bookings" ON public.bookings FOR UPDATE TO anon, authenticated USING (true); GRANT SELECT, INSERT, UPDATE, DELETE ON public.bookings TO anon;